//! Built-in CJK glyphs used as a fallback for characters that are neither in
//! the font itself nor in the translation blob (e.g. a Chinese translation,
//! whose glyphs would not fit into the blob).
//!
//! Each table is generated by `gen_cjk_font.py` and has the layout:
//!   - "CJK1" magic
//!   - u16 entry count, u16 reserved
//!   - entries sorted by codepoint: u16 codepoint, u16 reserved, u32 offset
//!     of the glyph data (relative to the end of the entries)
//!   - glyph data in the usual font format (5 byte header + bitmap)

const HEADER_LEN: usize = 8;
const ENTRY_LEN: usize = 8;

static CJK_SMALL: &[u8] = include_bytes!("cjk/cjk_20.bin");
static CJK_MEDIUM: &[u8] = include_bytes!("cjk/cjk_23.bin");
static CJK_LARGE: &[u8] = include_bytes!("cjk/cjk_34.bin");

fn read_u16(table: &[u8], pos: usize) -> u16 {
    u16::from_le_bytes([table[pos], table[pos + 1]])
}

fn read_u32(table: &[u8], pos: usize) -> usize {
    u32::from_le_bytes([
        table[pos],
        table[pos + 1],
        table[pos + 2],
        table[pos + 3],
    ]) as usize
}

fn lookup(table: &'static [u8], codepoint: u16) -> Option<&'static [u8]> {
    if table.len() < HEADER_LEN || &table[..4] != b"CJK1" {
        return None;
    }
    let count = usize::from(read_u16(table, 4));
    let data_start = HEADER_LEN + count * ENTRY_LEN;
    if table.len() < data_start {
        return None;
    }

    let entry_cp = |i: usize| read_u16(table, HEADER_LEN + i * ENTRY_LEN);
    let entry_offset = |i: usize| read_u32(table, HEADER_LEN + i * ENTRY_LEN + 4);

    let (mut lo, mut hi) = (0, count);
    while lo < hi {
        let mid = (lo + hi) / 2;
        let cp = entry_cp(mid);
        if cp == codepoint {
            let start = data_start + entry_offset(mid);
            let end = if mid + 1 < count {
                data_start + entry_offset(mid + 1)
            } else {
                table.len()
            };
            return table.get(start..end);
        } else if cp < codepoint {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    None
}

/// Returns the glyph of `codepoint` in the CJK size matching a font of
/// `font_height` pixels.
pub fn glyph(codepoint: u16, font_height: i16) -> Option<&'static [u8]> {
    let table = if font_height <= 24 {
        CJK_SMALL
    } else if font_height <= 30 {
        CJK_MEDIUM
    } else {
        CJK_LARGE
    };
    lookup(table, codepoint)
}
